-- sudo -u postgres psql
CREATE ROLE app_owner LOGIN PASSWORD 'Owner#2026';
CREATE ROLE app_user  LOGIN PASSWORD 'User#2026';
CREATE DATABASE appdb OWNER app_owner;
\l appdb

SELECT pg_catalog.set_config('search_path', '', false);
CREATE DATABASE reportdb OWNER app_owner ENCODING 'UTF8' TEMPLATE template0;
COMMENT ON DATABASE reportdb IS 'Reporting copy for the BI team';

SELECT datname, shobj_description(oid, 'pg_database') AS description
  FROM pg_database
 WHERE datname = 'reportdb';

SELECT datname, pg_encoding_to_char(encoding) AS encoding, datcollate
  FROM pg_database
 WHERE datname = 'legacydb';

ALTER DATABASE appdb CONNECTION LIMIT 50;
ALTER DATABASE appdb SET statement_timeout = '60s';
ALTER DATABASE appdb SET timezone = 'Asia/Kolkata';

SELECT datname, datconnlimit FROM pg_database WHERE datname = 'appdb';
\drds

CREATE DATABASE company_template;
\c company_template
CREATE SCHEMA audit;
CREATE TABLE audit.change_log (
  log_id     bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  table_name text NOT NULL,
  changed_by text NOT NULL DEFAULT current_user,
  changed_at timestamptz NOT NULL DEFAULT now()
);
\c postgres
ALTER DATABASE company_template IS_TEMPLATE true ALLOW_CONNECTIONS false;
SELECT datname, datistemplate, datallowconn FROM pg_database ORDER BY datname;

CREATE DATABASE branch_mumbai TEMPLATE company_template OWNER app_owner;
\c branch_mumbai
\dt audit.*

CREATE SCHEMA sales;
CREATE SCHEMA reporting;

CREATE TABLE sales.orders (
  order_id  int PRIMARY KEY,
  customer  text NOT NULL,
  amount    numeric(10,2) NOT NULL
);
INSERT INTO sales.orders VALUES
  (1, 'Asha Traders', 2500.00),
  (2, 'Ravi Stores', 1200.50);

-- an old test table with the same name, left in public
CREATE TABLE public.orders (
  order_id  int PRIMARY KEY,
  note      text
);
INSERT INTO public.orders VALUES (99, 'old test table in public');

\dn

SHOW search_path;
SELECT current_schema(), current_schemas(true);
SELECT * FROM orders;
SELECT * FROM sales.orders;

SET search_path TO sales, public;
SELECT current_schema();
SELECT * FROM orders;
CREATE TABLE customers (customer_id int PRIMARY KEY, name text);
\dt *.customers

SHOW search_path;
SELECT current_schema(), current_schemas(false);
CREATE TABLE scratch (id int);
\dt *.scratch

DROP SCHEMA reporting;
DROP SCHEMA sales;
DROP SCHEMA sales CASCADE;

DROP DATABASE testdb;
SELECT pid, usename, datname, state FROM pg_stat_activity WHERE datname = 'testdb';
DROP DATABASE testdb WITH (FORCE);

SET search_path TO saels;
SELECT current_schemas(false);
CREATE TABLE t1 (id int);

